REDUCE_OPS = {
    UnaryOperator.BitwiseOr: "|",
    UnaryOperator.BitwiseAnd: "&",
    UnaryOperator.BitwiseXor: "^",
    UnaryOperator.BitwiseNor: "~|",
    UnaryOperator.BitwiseNand: "~&",
    UnaryOperator.BitwiseXnor: "~^",
}
